 function poolTabs(scope?:string){return <div className="u-tabs u-pool-tabs" role="tablist" aria-label="未安排任务池">{(['day','week','cycle'] as const).map(kind=><button type="button" role="tab" aria-selected={poolKind===kind} className={poolKind===kind?'active':''} key={kind} onClick={()=>setPoolKind(kind)}>{POOL_LABELS[kind]}<span>{unscheduledPool(data,kind,scope).length}</span></button>)}</div>;}
